   116	                Keyword::Drop => self.parse_drop_table(),
   117	                Keyword::Delete => self.parse_delete(),
   118	                Keyword::Insert => self.parse_insert(),
   119	                Keyword::Update => self.parse_update(),
   120	                Keyword::Select => self.parse_select(),
   121	                _ => Err(errinput!("unexpected keyword {}", kw)),
   122	            }
   123	        } else {
   124	            Err(errinput!("expected SQL statement"))
   125	        }
   126	    }
