   153	    /// Parses a CREATE TABLE statement.
   154	    fn parse_create_table(&mut self) -> Result<ast::Statement> {
   155	        self.expect(Token::Keyword(Keyword::Create))?;
   156	        self.expect(Token::Keyword(Keyword::Table))?;
   157	        let name = self.next_ident()?;
   158	        self.expect(Token::OpenParen)?;
   159	        let mut columns = Vec::new();
   160	        let mut first = true;
   161	        while !self.next_is(Token::CloseParen) {
   162	            if !first {
   163	                self.expect(Token::Comma)?;
   164	            }
   165	            first = false;
   166	            columns.push(self.parse_create_table_column()?);
   167	        }
   168	        self.expect(Token::CloseParen)?;
