   172	    /// Parses a CREATE TABLE column definition.
   173	    fn parse_create_table_column(&mut self) -> Result<ast::Column> {
   174	        let name = self.next_ident()?;
   175	        let data_type = self.parse_data_type()?;
   176	        let mut nullable = true;
   177	        let mut default = None;
   178	        while let Some(kw) = self.next_if_keyword() {
   179	            match kw {
   180	                Keyword::Null => {
   181	                    if self.next_is(Token::Keyword(Keyword::Not)) {
   182	                        nullable = false;
   183	                    }
   184	                }
   185	                Keyword::Default => {
   186	                    default = Some(self.parse_expression()?);
   187	                }
   188	                _ => {
   189	                    return Err(errinput!("unexpected keyword {}", kw));
   190	                }
   191	            }
   192	        }
   193	        Ok(ast::Column {
   194	            name,
   195	            data_type,
   196	            nullable,
   197	            default,
   198	        })
   199	    }
