   201	    /// Parses a DROP TABLE statement.
   202	    fn parse_drop_table(&mut self) -> Result<ast::Statement> {
   203	        self.expect(Token::Keyword(Keyword::Drop))?;
   204	        self.expect(Token::Keyword(Keyword::Table))?;
