   227	            if !first {
   228	                self.expect(Token::Comma)?;
   229	            }
   230	            first = false;
   231	            columns.push(self.next_ident()?);
   232	        }
   233	        self.expect(Token::CloseParen)?;
   234	        self.expect(Token::Keyword(Keyword::Values))?;
   235	        self.expect(Token::OpenParen)?;
   236	        let mut values = Vec::new();
   237	        first = true;
   238	        while !self.next_is(Token::CloseParen) {
   239	            if !first {
   240	                self.expect(Token::Comma)?;
   241	            }
   242	            first = false;
   243	            values.push(self.parse_expression()?);
   244	        }
   245	        self.expect(Token::CloseParen)?;
