   259	        let mut first = true;
   260	        while !self.next_is(Token::Where) {
   261	            if !first {
   262	                self.expect(Token::Comma)?;
   263	            }
   264	            first = false;
   265	            let column = self.next_ident()?;
   266	            self.expect(Token::Equal)?;
   267	            assignments.push((column, self.parse_expression()?));
