   300	    /// Parses a SELECT clause, if present.
   301	    fn parse_select_clause(&mut self) -> Result<Vec<(ast::Expression, Option<String>)>> {
   302	        let mut select = Vec::new();
   303	        let mut first = true;
   304	        while !self.next_is(Token::Keyword(Keyword::From))
   305	            && !self.next_is(Token::Keyword(Keyword::Where))
   306	            && !self.next_is(Token::Keyword(Keyword::Group))
   307	            && !self.next_is(Token::Keyword(Keyword::Order))
   308	            && !self.next_is(Token::Keyword(Keyword::Limit))
   309	            && !self.next_is(Token::Keyword(Keyword::Offset))
   310	            && !self.next_is(Token::Semicolon)
   311	        {
   312	            if !first {
   313	                self.expect(Token::Comma)?;
   314	            }
   315	            first = false;
   316	            let expr = self.parse_expression()?;
   317	            let alias = if self.next_is(Token::Keyword(Keyword::As)) {
   318	                Some(self.next_ident()?)
   319	            } else {
   320	                None
   321	            };
   322	            select.push((expr, alias));
   323	        }
   324	        Ok(select)
   325	    }
   326	
   327	    /// Parses a FROM clause, if present.
   328	    fn parse_from_clause(&mut self) -> Result<Vec<ast::From>> {
   329	        let mut from = Vec::new();
   330	        self.expect(Token::Keyword(Keyword::From))?;
   331	        loop {
   332	            from.push(self.parse_from_table()?);
   333	            if let Some(join_type) = self.parse_from_join()? {
   334	                from.push(ast::From::Join {
   335	                    left: Box::new(from.pop().unwrap()),
   336	                    join_type,
   337	                    right: Box::new(self.parse_from_table()?),
   338	                    condition: self.parse_where_clause()?,
   339	                });
   340	            } else {
   341	                break;
   342	            }
   343	        }
   344	        Ok(from)
   345	    }
   346	
   347	    // Parses a FROM table.
   348	    fn parse_from_table(&mut self) -> Result<ast::From> {
   349	        let table = self.next_ident()?;
   350	        let alias = if self.next_is(Token::Keyword(Keyword::As)) {
   351	            Some(self.next_ident()?)
   352	        } else {
   353	            None
   354	        };
   355	        Ok(ast::From::Table { table, alias })
   356	    }
   357	
   358	    // Parses a FROM JOIN type, if present.
   359	    fn parse_from_join(&mut self) -> Result<Option<ast::JoinType>> {
   360	        if let Some(kw) = self.next_if_keyword() {
   361	            match kw {
   362	                Keyword::Inner => {
   363	                    self.expect(Token::Keyword(Keyword::Join))?;
   364	                    Ok(Some(ast::JoinType::Inner))
   365	                }
   366	                Keyword::Left => {
   367	                    self.expect(Token::Keyword(Keyword::Join))?;
   368	                    Ok(Some(ast::JoinType::Left))
   369	                }
   370	                Keyword::Right => {
   371	                    self.expect(Token::Keyword(Keyword::Join))?;
   372	                    Ok(Some(ast::JoinType::Right))
   373	                }
   374	                Keyword::Cross => {
   375	                    self.expect(Token::Keyword(Keyword::Join))?;
   376	                    Ok(Some(ast::JoinType::Cross))
   377	                }
   378	                _ => Err(errinput!("unexpected keyword {}", kw)),
   379	            }
   380	        } else {
   381	            Ok(None)
   382	        }
   383	    }
   384	
   385	    /// Parses a WHERE clause, if present.
   386	    fn parse_where_clause(&mut self) -> Result<Option<ast::Expression>> {
   387	        if self.next_is(Token::Keyword(Keyword::Where)) {
   388	            Ok(Some(self.parse_expression()?))
   389	        } else {
   390	            Ok(None)
   391	        }
   392	    }
   393	
   394	    /// Parses a GROUP BY clause, if present.
   395	    fn parse_group_by_clause(&mut self) -> Result<Vec<ast::Expression>> {
   396	        let mut group_by = Vec::new();
   397	        self.expect(Token::Keyword(Keyword::Group))?;
   398	        self.expect(Token::Keyword(Keyword::By))?;
   399	        let mut first = true;
   400	        while !self.next_is(Token::Keyword(Keyword::Having))
   401	            && !self.next_is(Token::Keyword(Keyword::Order))
   402	            && !self.next_is(Token::Keyword(Keyword::Limit))
   403	            && !self.next_is(Token::Keyword(Keyword::Offset))
   404	            && !self.next_is(Token::Semicolon)
   405	        {
   406	            if !first {
   407	                self.expect(Token::Comma)?;
   408	            }
   409	            first = false;
   410	            group_by.push(self.parse_expression()?);
   411	        }
   412	        Ok(group_by)
   413	    }
   414	
   415	    /// Parses a HAVING clause, if present.
   416	    fn parse_having_clause(&mut self) -> Result<Option<ast::Expression>> {
   417	        if self.next_is(Token::Keyword(Keyword::Having)) {
   418	            Ok(Some(self.parse_expression()?))
   419	        } else {
   420	            Ok(None)
   421	        }
   422	    }
