   425	    fn parse_order_by_clause(&mut self) -> Result<Vec<(ast::Expression, ast::Direction)>> {
   426	        let mut order_by = Vec::new();
   427	        self.expect(Token::Keyword(Keyword::Order))?;
   428	        self.expect(Token::Keyword(Keyword::By))?;
   429	        let mut first = true;
